// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Campground.Shared.Contracts;
using Campground.Shared.Injection;
using Campground.Shared.Network;
using MediaBrowser.Common.Configuration;
using MediaBrowser.Controller.Configuration;
using Microsoft.AspNetCore.Http;

namespace Campground.Shared.Setup
{
    /// <summary>Result level of a setup check.</summary>
    internal enum CheckLevel
    {
        Ok,
        Info,
        Warning,
        Problem,
    }

    /// <summary>One line on a plugin's "Setup checks" panel.</summary>
    /// <param name="Id">Stable id, e.g. "known-proxies".</param>
    /// <param name="Level">How bad.</param>
    /// <param name="Title">Short plain-English title.</param>
    /// <param name="Detail">What we saw and how to fix it.</param>
    /// <param name="FixProvider">Plugin id that offers a one-click fix, if any.</param>
    internal sealed record SetupCheck(string Id, CheckLevel Level, string Title, string Detail, string? FixProvider = null);

    /// <summary>
    /// The checks every Campground plugin shows the same way. Each check is pure (feed it facts) so it can be
    /// tested; <see cref="RunAll"/> gathers the facts from Jellyfin and the current request.
    /// </summary>
    internal static class SetupChecks
    {
        /// <summary>Runs every shared check for the admin's current request.</summary>
        internal static IReadOnlyList<SetupCheck> RunAll(HttpContext context, IServerConfigurationManager serverConfig, bool needsHardwareEncoder = false)
        {
            var results = new List<SetupCheck>();
            NetworkSettings? settings = null;
            try
            {
                settings = JellyfinNetworkSettings.Read(serverConfig);
            }
            catch (Exception ex)
            {
                results.Add(new SetupCheck("network-config", CheckLevel.Warning, "Couldn't read Jellyfin's network settings", ex.Message));
            }

            if (settings != null)
            {
                var connection = context.Connection.RemoteIpAddress;
                var xff = context.Request.Headers["X-Forwarded-For"].ToString();
                var classification = JellyfinNetworkSettings.Classify(context, serverConfig);
                results.Add(KnownProxies(NetworkClassifier.IsUntrustedProxyProblem(connection, xff, settings), connection?.ToString()));
                results.Add(BaseUrl(settings.BaseUrl, context.Request.PathBase.Value, context.Request.Path.Value));
                results.Add(PublishedUrl(settings.PublishedServerUris));
                results.Add(Https(HttpsClient.Evaluate(context.Request.IsHttps, classification, settings)));
            }

            try
            {
                var enc = serverConfig.GetEncodingOptions();
                var temp = string.IsNullOrWhiteSpace(enc.TranscodingTempPath)
                    ? Path.Combine(serverConfig.ApplicationPaths.CachePath, "transcodes")
                    : enc.TranscodingTempPath;
                results.Add(TranscodeDisk(temp, FreeBytes(temp)));
                results.Add(HardwareEncoder(enc.HardwareAccelerationType.ToString(), needsHardwareEncoder));
            }
            catch (Exception ex)
            {
                results.Add(new SetupCheck("encoding-config", CheckLevel.Info, "Couldn't read Jellyfin's encoding settings", ex.Message));
            }

            results.Add(Injection(InjectionCoordinator.Health()));
            return results;
        }

        internal static SetupCheck KnownProxies(bool untrustedProxy, string? connection)
            => untrustedProxy
                ? new SetupCheck(
                    "known-proxies",
                    CheckLevel.Problem,
                    "Your reverse proxy isn't in Known proxies",
                    $"Requests arrive from {connection ?? "a proxy"} with X-Forwarded-For, but that address isn't listed under Dashboard → Networking → Known proxies. Jellyfin and Campground can't see real client addresses, so remote/local decisions and rate limits are wrong. Add the proxy's address there.")
                : new SetupCheck("known-proxies", CheckLevel.Ok, "Proxy settings look right", "No untrusted forwarding seen on this request.");

        internal static SetupCheck BaseUrl(string configuredBaseUrl, string? pathBase, string? requestPath)
        {
            var configured = JellyfinNetworkSettings.NormalizeBaseUrl(configuredBaseUrl);
            var seen = (pathBase ?? string.Empty) + (requestPath ?? string.Empty);
            if (configured.Length > 0 && !seen.StartsWith(configured, StringComparison.OrdinalIgnoreCase))
            {
                return new SetupCheck(
                    "base-url",
                    CheckLevel.Warning,
                    "Base URL doesn't match this request",
                    $"Jellyfin's Base URL is \"{configured}\" but this page was requested at \"{seen}\". If a proxy strips the prefix, scripts may load from the wrong path.");
            }

            return new SetupCheck("base-url", CheckLevel.Ok, "Base URL is consistent", configured.Length == 0 ? "No Base URL set." : $"Base URL \"{configured}\".");
        }

        internal static SetupCheck PublishedUrl(IReadOnlyList<string> published)
            => published.Count == 0
                ? new SetupCheck("published-url", CheckLevel.Info, "No published server URL", "Optional. Set Dashboard → Networking → Published server URIs if clients outside your network should use a specific address.")
                : new SetupCheck("published-url", CheckLevel.Ok, "Published server URL set", string.Join(", ", published));

        internal static SetupCheck Https(HttpsReadiness r)
            => r.State switch
            {
                HttpsState.Ready => new SetupCheck("https", CheckLevel.Ok, "HTTPS is working", r.Detail),
                HttpsState.Unverified => new SetupCheck("https", CheckLevel.Warning, "HTTPS can't be confirmed", r.Detail, r.FixProvider),
                _ => new SetupCheck("https", CheckLevel.Warning, "HTTPS isn't set up", r.Detail + " Some features (game streaming, controllers) need HTTPS.", r.FixProvider),
            };

        internal static SetupCheck TranscodeDisk(string path, long? freeBytes)
        {
            if (freeBytes == null)
            {
                return new SetupCheck("transcode-disk", CheckLevel.Info, "Transcode folder space unknown", $"Couldn't read free space for {path}.");
            }

            var gib = freeBytes.Value / (1024.0 * 1024 * 1024);
            var level = gib < 2 ? CheckLevel.Problem : gib < 10 ? CheckLevel.Warning : CheckLevel.Ok;
            return new SetupCheck("transcode-disk", level, level == CheckLevel.Ok ? "Transcode folder has space" : "Transcode folder is low on space", $"{gib:0.0} GiB free at {path}.");
        }

        internal static SetupCheck HardwareEncoder(string accelerationType, bool required)
        {
            var none = string.IsNullOrEmpty(accelerationType) || accelerationType.Equals("none", StringComparison.OrdinalIgnoreCase);
            if (!none)
            {
                return new SetupCheck("hw-encoder", CheckLevel.Ok, "Hardware encoding is on", accelerationType);
            }

            return new SetupCheck(
                "hw-encoder",
                required ? CheckLevel.Problem : CheckLevel.Info,
                "Hardware encoding is off",
                required
                    ? "This plugin needs a hardware video encoder. Turn it on under Dashboard → Playback → Transcoding."
                    : "Optional. Turning it on under Dashboard → Playback → Transcoding lowers CPU use.");
        }

        internal static SetupCheck Injection(InjectionHealth h)
        {
            if (h.RegisteredPlugins.Count == 0)
            {
                return new SetupCheck("injection", CheckLevel.Info, "No web scripts registered", "No Campground plugin has browser features turned on.");
            }

            if (!h.MiddlewareActive || h.ServedCount == 0)
            {
                return new SetupCheck("injection", CheckLevel.Warning, "Web scripts not served yet", "Reload the web client. If this stays, another plugin or a proxy cache may be serving index.html. " + (h.LastError ?? string.Empty));
            }

            var owner = h.OwnerVersion == null ? h.OwnerPluginId : $"{h.OwnerPluginId} {h.OwnerVersion}";
            if (h.LastError != null)
            {
                return new SetupCheck("injection", CheckLevel.Warning, "Web scripts had an error", h.LastError + $" (index.html owner: {owner})");
            }

            if (h.NewerThanOwner is { } newer)
            {
                return new SetupCheck(
                    "injection",
                    CheckLevel.Warning,
                    "Restart Jellyfin to use the newest web-script code",
                    $"index.html owner: {owner}. {newer.PluginId} carries the newer {newer.Version} but was loaded after the owner was chosen. Restart the Jellyfin process (on Docker, restart the container) so {newer.PluginId} takes over.");
            }

            return new SetupCheck("injection", CheckLevel.Ok, "Web scripts are loading", $"index.html owner: {owner}. Served {h.ServedCount} times; plugins: {string.Join(", ", h.RegisteredPlugins)}.");
        }

        private static long? FreeBytes(string path)
        {
            try
            {
                var root = Path.GetPathRoot(Path.GetFullPath(path));
                return root == null ? null : DriveInfo.GetDrives().Where(d => d.IsReady && path.StartsWith(d.Name, StringComparison.OrdinalIgnoreCase))
                    .OrderByDescending(d => d.Name.Length).Select(d => (long?)d.AvailableFreeSpace).FirstOrDefault() ?? new DriveInfo(root).AvailableFreeSpace;
            }
            catch (Exception)
            {
                return null;
            }
        }
    }
}
